"""Exception hierarchy for notekeeper.

Every error the library raises derives from :class:`NoteKeeperError`, so callers
(CLI, tests) can catch a single base class.
"""

from __future__ import annotations

__all__ = ["NoteKeeperError", "NoteNotFoundError", "StorageError", "InvalidNoteError"]


class NoteKeeperError(Exception):
    """Base class for all notekeeper errors."""


class NoteNotFoundError(NoteKeeperError, KeyError):
    """A note id does not exist in the store."""

    def __init__(self, note_id: int) -> None:
        super().__init__(f"note {note_id} not found")
        self.note_id = note_id


class StorageError(NoteKeeperError):
    """The JSON file could not be read or written."""

    def __init__(self, message: str, *, path: object = None) -> None:
        if path is not None:
            message = f"{message} (path: {path})"
        super().__init__(message)
        self.path = path


class InvalidNoteError(NoteKeeperError, ValueError):
    """A title, body or tag is not acceptable (also a ValueError)."""

"""The :class:`Note` value object: validation, normalisation, JSON conversion."""

from __future__ import annotations

import re
from datetime import datetime, timezone
from typing import Any, Iterable

from .errors import InvalidNoteError

__all__ = ["Note", "normalize_tag", "utc_now"]

_TAG_MAX = 32
_TAG_RE = re.compile(r"^\w[\w-]*$", re.UNICODE)


def utc_now() -> datetime:
    """Timezone-aware current time in UTC."""
    return datetime.now(timezone.utc)


def normalize_tag(tag: str) -> str:
    """Trim, collapse inner whitespace to ``_`` and lowercase a tag.

    Raises :class:`InvalidNoteError` if the result is empty, longer than
    ``_TAG_MAX`` characters or contains characters other than letters, digits,
    ``_`` and ``-``.
    """
    if not isinstance(tag, str):
        raise InvalidNoteError(f"tag must be a string, got {type(tag).__name__}")
    cleaned = re.sub(r"\s+", "_", tag.strip()).lower()
    if not cleaned:
        raise InvalidNoteError("tag cannot be empty")
    if len(cleaned) > _TAG_MAX:
        raise InvalidNoteError(f"tag {cleaned!r} is longer than {_TAG_MAX} characters")
    if not _TAG_RE.match(cleaned):
        raise InvalidNoteError(
            f"tag {cleaned!r} may only contain letters, digits, '_' and '-'"
        )
    return cleaned


def _to_datetime(value: Any, field: str) -> datetime:
    if isinstance(value, datetime):
        stamp = value
    elif isinstance(value, str):
        try:
            stamp = datetime.fromisoformat(value)
        except ValueError as exc:  # pragma: no cover - message kept short
            raise InvalidNoteError(f"{field} is not an ISO-8601 timestamp: {value!r}") from exc
    else:
        raise InvalidNoteError(f"{field} must be an ISO-8601 string, got {value!r}")
    if stamp.tzinfo is None:
        stamp = stamp.replace(tzinfo=timezone.utc)
    return stamp.astimezone(timezone.utc)

"""The :class:`Note` value object: validation, normalisation, JSON conversion."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any, Iterable

from .errors import InvalidNoteError

__all__ = ["Note", "normalize_tag", "utc_now"]

TAG_MAX_LENGTH = 32
_TAG_RE = re.compile(r"^\w[\w\-]*$", re.UNICODE)


def utc_now() -> datetime:
    """Timezone-aware current time in UTC (truncated to seconds)."""
    return datetime.now(timezone.utc).replace(microsecond=0)


def normalize_tag(tag: Any) -> str:
    """Trim, collapse inner whitespace to ``_`` and lowercase a tag.

    Raises :class:`InvalidNoteError` when the result is empty, longer than
    :data:`TAG_MAX_LENGTH` characters, or contains characters other than
    letters, digits, ``_`` and ``-``.
    """
    if not isinstance(tag, str):
        raise InvalidNoteError(f"tag must be a string, got {type(tag).__name__}")
    cleaned = re.sub(r"\s+", "_", tag.strip()).lower()
    if not cleaned:
        raise InvalidNoteError("tag cannot be empty")
    if len(cleaned) > TAG_MAX_LENGTH:
        raise InvalidNoteError(
            f"tag {cleaned!r} is longer than {TAG_MAX_LENGTH} characters"
        )
    if not _TAG_RE.match(cleaned):
        raise InvalidNoteError(
            f"tag {cleaned!r} may only contain letters, digits, '_' and '-'"
        )
    return cleaned


def _normalize_tags(tags: Iterable[Any] | None) -> tuple[str, ...]:
    if tags is None:
        return ()
    if isinstance(tags, (str, bytes)):
        raise InvalidNoteError("tags must be an iterable of strings, not a bare string")
    seen: dict[str, None] = {}
    for raw in tags:
        seen.setdefault(normalize_tag(raw), None)
    return tuple(seen)


def _to_datetime(value: Any, label: str) -> datetime:
    if isinstance(value, datetime):
        stamp = value
    elif isinstance(value, str):
        try:
            stamp = datetime.fromisoformat(value)
        except ValueError as exc:
            raise InvalidNoteError(
                f"{label} is not an ISO-8601 timestamp: {value!r}"
            ) from exc
    else:
        raise InvalidNoteError(
            f"{label} must be an ISO-8601 string, got {type(value).__name__}"
        )
    if stamp.tzinfo is None:
        stamp = stamp.replace(tzinfo=timezone.utc)
    return stamp.astimezone(timezone.utc)


def _clean_text(value: Any, label: str) -> str:
    if not isinstance(value, str):
        raise InvalidNoteError(f"{label} must be a string, got {type(value).__name__}")
    text = value.strip()
    if not text:
        raise InvalidNoteError(f"{label} cannot be empty")
    return text


@dataclass
class Note:
    """A single note. ``tags`` is always normalised, de-duplicated and sorted."""

    title: str
    body: str = ""
    tags: tuple[str, ...] = field(default=())
    id: int | None = None
    created_at: datetime = field(default_factory=utc_now)
    updated_at: datetime = field(default_factory=utc_now)

    def __post_init__(self) -> None:
        self.title = _clean_text(self.title, "title")
        if not isinstance(self.body, str):
            raise InvalidNoteError(
                f"body must be a string, got {type(self.body).__name__}"
            )
        self.body = self.body.strip()
        self.tags = tuple(sorted(_normalize_tags(self.tags)))
        self.created_at = _to_datetime(self.created_at, "created_at")
        self.updated_at = _to_datetime(self.updated_at, "updated_at")

    # ------------------------------------------------------------------ text
    @property
    def preview(self) -> str:
        """First line of the body, single-spaced, for one-line listings."""
        return self.body.splitlines()[0] if self.body else ""

    def matches(self, needle: str) -> bool:
        """Case-insensitive substring test over title, body and tags."""
        term = needle.strip().lower()
        if not term:
            return True
        if term in self.title.lower() or term in self.body.lower():
            return True
        return any(term in tag for tag in self.tags)

    # ------------------------------------------------------------------ JSON
    def to_dict(self) -> dict[str, Any]:
        """JSON-safe mapping (ISO-8601 UTC timestamps, ``Z`` suffix)."""
        return {
            "id": self.id,
            "title": self.title,
            "body": self.body,
            "tags": list(self.tags),
            "created_at": self.created_at.isoformat().replace("+00:00", "Z"),
            "updated_at": self.updated_at.isoformat().replace("+00:00", "Z"),
        }

    @classmethod
    def from_dict(cls, data: Any) -> "Note":
        """Rebuild a note from :meth:`to_dict`; ``from_dict(n.to_dict())`` round-trips."""
        if not isinstance(data, dict):
            raise InvalidNoteError(
                f"note must be an object, got {type(data).__name__}"
            )
        missing = [key for key in ("title", "created_at", "updated_at") if key not in data]
        if missing:
            raise InvalidNoteError(f"note is missing field(s): {', '.join(missing)}")
        note_id = data.get("id")
        if note_id is not None and (not isinstance(note_id, int) or isinstance(note_id, bool)):
            raise InvalidNoteError(f"id must be an integer or null, got {note_id!r}")
        tags = data.get("tags", [])
        if isinstance(tags, str) or not isinstance(tags, (list, tuple)):
            raise InvalidNoteError(f"tags must be a list, got {type(tags).__name__}")
        return cls(
            title=data["title"],
            body=data.get("body", ""),
            tags=tags,
            id=note_id,
            created_at=data["created_at"],
            updated_at=data["updated_at"],
        )

