    "search": _cmd_search, "delete": _cmd_delete, "tag": _cmd_tag,
    "untag": _cmd_untag, "tags": _cmd_tags, "edit": _cmd_edit}


def _dispatch(parser: Parser, argv: list[str] | None) -> int:
    """Parse ``argv`` and run the handler of the chosen subcommand."""
    args = parser.parse_args(argv)
    handler = _COMMAND_HANDLERS.get(getattr(args, "command", None) or "")
    if handler is None:  # `notekeeper` alone: help on stdout, usage code 2
        _emit(parser.format_help().rstrip("\n"))
        return 2
    _command_parser(parser, args)  # claim "notekeeper COMMAND" as the usage prog
    return handler(parser, _store(args), args)


def _exit_code(request: SystemExit) -> int:
    """argparse's SystemExit -> the code to return: 0 for ``-h``/``-V``, else 2."""
    code = request.code
    if code is None:
        return 0
    return code if isinstance(code, int) else 2


def main(argv: list[str] | None = None) -> int:
    """Run one CLI invocation and return its exit code.

    Never raises for a failure the library documents: bad input, an unknown id,
    an unusable store or Ctrl-C all come back as 1, 2 or 130.
    """
    try:
        return _dispatch(build_parser(), argv)
    except SystemExit as request:  # argparse usage error, --help, --version
        return _exit_code(request)
    except KeyboardInterrupt:
        sys.stderr.write("Interrupted.\n")
        return 130
    except NoteKeeperError as exc:
        return _emit_error(exc)


def run(argv: list[str] | None = None) -> int:
    """Entry point of the ``notekeeper`` console script: same as :func:`main`."""
    return main(argv)


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())
